function sum(arr) {
  let res = 0;
  for (x of arr) {res += x;}
  return res;
}

function vDot(a,b){
	return sum(a.map((t,k)=>t*b[k]))
}

function vNorm(a){
	let s1 = sum(a.map((t)=>t*t))
	return a.map((t)=>t/s1)
}

function vMag(a){
	var s1 = sum(a.map((t)=>t*t))
	return s1
}

function vDst(a, b){
	var s1 = sqrt(sum(a.map((t,k)=>(t-b[k])**2)))
	return s1
}

function vMbyc(a, c){
	return a.map((t)=>t*c)
}

function vAdd(a,b){
	return a.map((t,k)=>t+b[k])
}

function vSub(a,b){
	return a.map((t,k)=>t-b[k])
}

//let dist= dotProduct(p.normal, (vectorSubtract(point, p.point)));
function d_from_plane(n, p, target){
	return vDot(n, vSub(target, p))
}

function d_from_plane_set(n, p, s){
	return sum(s.map(t => d_from_plane(n, p, t)))
}

function s_p_intr(n,p,seg){
	// line plane intersection
	// n: normal plane eg [1,0,0]
	// p: point plane eg [1,1,1]
	// seg: segment eg [[1,2,3], [4,5,6]]
	let ray = vSub(seg[1],seg[0])
	let rayOrigin = seg[0]
	let d = vDot(n, p)
	if(vDot(n,ray) == 0){return false;}
	let x = (d - vDot(n, rayOrigin)) / vDot(n, ray);
	if(x>1){return false}
	if(x<0){return false}
	let contact = vAdd(rayOrigin,vMbyc((ray),x))

	return contact
}

function spilt_poly3(n, p, poly,) {
	poly.push(poly[0])

	let int_points  = [ ];
	let pr_p = poly[0]
	let k = 0;
	let new_points = [pr_p, ]
	let out1 = []
	let out2 = []

	let extra_line = []

	for (a=1;a<poly.length;a+=1) {
    let tr_p = s_p_intr(n, p, [pr_p, poly[a]])
		if (tr_p != false){ 
			k += 1
			new_points.push([tr_p[0], tr_p[1], tr_p[2]])
			extra_line.push([tr_p[0], tr_p[1], tr_p[2]])
			int_points.push(k) 
		}
		k += 1
		new_points.push(poly[a])
		pr_p = poly[a]
  }
	for (a = int_points[0]; a < new_points.length*3; a+=1) {
		let ta = a%new_points.length;
		out1.push(new_points[ta])
		if (ta == int_points[1]){break}
	}
	for (a = int_points[1]; a < new_points.length*3; a+=1) {
		var ta = a%new_points.length;
		out2.push(new_points[ta])
		if (ta == int_points[0]){break}
	}


	if(out1.length <1 && out2.length <1){
		out1 = poly.slice(0, -1)
	}

	if((out1.length >1 || out2.length >1) && d_from_plane_set(n, p, out1)<0){
		let t4 = out1
		out1 = out2
		out2 = t4
	}

	return [out1, out2, extra_line]
}



function sortPointsClockwise(points) {
  if (!points || points.length <= 1) {
    return points || []; // Return empty array if input is null/undefined or empty, otherwise return as is
  }

  // 1. Calculate the centroid of the points
  let centroidX = 0;
  let centroidY = 0;
  for (const point of points) {
    centroidX += point[0]; // Assuming x is at index 0
    centroidY += point[1]; // Assuming y is at index 1
  }
  centroidX /= points.length;
  centroidY /= points.length;

  function compareAngles(point1, point2) {
    const angle1 = Math.atan2(point1[1] - centroidY, point1[0] - centroidX);
    const angle2 = Math.atan2(point2[1] - centroidY, point2[0] - centroidX);
    return angle2 - angle1;
  }
  const sortedPoints = [...points];
  sortedPoints.sort(compareAngles);
  return sortedPoints;
}

function split_body(n,p,inp_body){
	let extra_face = [ ]
	let all_chunks = []
	let pieces_1 = [ ]
	let pieces_2 = [ ]

	inp_body.map(t => {
		let res2 = spilt_poly3(n, p, t)
		if(res2[0].length > 1) all_chunks.push(res2[0])
		if(res2[1].length > 1) all_chunks.push(res2[1])
		if(res2[2].length > 1) res2[2].map(t => extra_face.push(t))
	})

	if(all_chunks.length < 2){
		return [inp_body, []]
	}

	all_chunks.map(t=>{
		if(t.length <= 1) return;
		if(d_from_plane_set(n, p, t)<0){
			pieces_1.push(t)
		}else{
			pieces_2.push(t)
		}
	})

	if(extra_face.length > 1){
		extra_face = sortPointsClockwise(deduplicatePoints(extra_face))
		let other_one = [...extra_face]
		pieces_1.push(extra_face)
		pieces_2.push(other_one)
	}

	return [pieces_1, pieces_2]
}






