function generateCubeFaces(r) {
	// by claude-3-7-sonnet-20250219
  // The 6 faces of a cube (front, back, right, left, top, bottom)
  const faces = [];
  // Front face (z = r)
  faces.push([
    [-r, -r, r],  // bottom-left
    [r, -r, r],   // bottom-right
    [r, r, r],    // top-right
    [-r, r, r]    // top-left
  ]);
  // Back face (z = -r)
  faces.push([
    [r, -r, -r],   // bottom-right
    [-r, -r, -r],  // bottom-left
    [-r, r, -r],   // top-left
    [r, r, -r]     // top-right
  ]);
  // Right face (x = r)
  faces.push([
    [r, -r, r],    // bottom-front
    [r, -r, -r],   // bottom-back
    [r, r, -r],    // top-back
    [r, r, r]      // top-front
  ]);
  // Left face (x = -r)
  faces.push([
    [-r, -r, -r],  // bottom-back
    [-r, -r, r],   // bottom-front
    [-r, r, r],    // top-front
    [-r, r, -r]    // top-back
  ]);
  // Top face (y = r)
  faces.push([
    [-r, r, r],    // front-left
    [r, r, r],     // front-right
    [r, r, -r],    // back-right
    [-r, r, -r]    // back-left
  ]);
  // Bottom face (y = -r)
  faces.push([
    [-r, -r, -r],  // back-left
    [r, -r, -r],   // back-right
    [r, -r, r],    // front-right
    [-r, -r, r]    // front-left
  ]);
  return faces;
}


function deduplicatePoints(points, epsilon = 0.001) {
		//by gpt-4.5-preview-2025-02-27
    const deduped = [];
    for (const point of points) {
        let isDuplicate = false;
        for (const existing of deduped) {
            const dx = point[0] - existing[0];
            const dy = point[1] - existing[1];
            const dz = point[2] - existing[2];
            const distanceSquared = dx*dx + dy*dy + dz*dz;

            if (distanceSquared <= epsilon * epsilon) {
                isDuplicate = true;
                break;
            }
        }
        if (!isDuplicate) {
            deduped.push(point);
        }
    }
    return deduped;
}


function calculateNormal(points) {
    // by mistral-large-2411
    // Ensure the input is a list of three points, each with three coordinates
    // if (points.length !== 3 || points.some(p => p.length !== 3)) {
    //     throw new Error("Input must be a list of three points, each with three coordinates");
    // }

    // Extract the points
    const [p1, p2, p3] = points;
    // Calculate vectors U and V
    const U = [p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]];
    const V = [p3[0] - p1[0], p3[1] - p1[1], p3[2] - p1[2]];
    // Compute the cross product of U and V
    const normal = [
        U[1] * V[2] - U[2] * V[1],
        U[2] * V[0] - U[0] * V[2],
        U[0] * V[1] - U[1] * V[0]
    ];
    return normal;
}

function gen_half_space(r){
	let tr = [[random(-r, r),random(-r, r),random(-r, r)],
						[random(-r, r),random(-r, r),random(-r, r)],
						[random(-r, r),random(-r, r),random(-r, r)],]
	let nr = vNorm(calculateNormal(tr))
	return [nr, tr[0]]
}




